            for item in vals:
                p = pos(item)
                if p is not None:
                    candidates.append(p)
        if not candidates:
            opp = pos(observation.get("opponent_position"))
            if opp is not None:
                return step_toward((sx, sy), opp)
            return [0, 0]
        target = best_by_distance(candidates, (sx, sy))
        if target is None:
            return [0, 0]
        return step_toward((sx, sy), target)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    res_pos = []
    for item in resources:
        p = pos(item)
        if p is not None:
            res_pos.append(p)

